-- GENERATED by `wfj generate` from data/gossip/gossip-24.jsonl. Do not edit: `wfj validate` regenerates and diffs it.
local _, WFJ = ...
WFJ.Data.add("gossip", {
  ["240042af8130e656"] = { "Porti la contaminazione del Flagello. Preparati a entrare nella ⟦Twisting Nether=Distorsione Fatua⟧.", "." },
  ["24014b63002477cd"] = { "BRUCIATE! Miserabili! BRUCIATE!", "." },
  ["2404c737894c223a"] = { "Cosa... cos'è questo? Potrebbe essere la risposta alle mie preghiere? Elune mi ha concesso un'arma, questa falce, per sconfiggere i demoni.", "." },
  ["2409e496d6c7208b"] = { "Le guardie di Theramore sono il miglior corpo di soldati dell'⟦Alliance=Alleanza⟧ di stanza a Kalimdor. È nostro dovere far rispettare le leggi dell'⟦Alliance=Alleanza⟧ anche così lontano da casa.", "." },
  ["240f77ef48815fa9"] = { "Cerchi il corriere? È appena volato via come un uccellino.\n\nNon posso dargli torto, povero diavolo. Questi wendigo sono una brutta faccenda.", "." },
  ["24118e12d94ae6de"] = { "I conciatori abbastanza abili, per esempio, possono piazzare una tenda come questa dietro di me.", "." },
  ["2412598b3bc8f8d8"] = { "La tossina è pronta, {name}.", "." },
  ["241e355a0e75630e"] = { "Ci siamo, Remulos.", "." },
  ["2425369e9e5aa2ee"] = { "Sei <tonto/tonta>? Di chi altro potrei parlare? Sì, la ragazza: la signora Mar'alith. Comunque, era tornata e non di ottimo umore. È lì che sono cominciate a fioccare le richieste.", "." },
  ["2426c8ccbe0120f9"] = { "La pagherai per ciò che hai fatto a Trey, {race}!", "." },
  ["242a32e6c1c695f4"] = { "Ho bisogno di un passaggio per andarmene da qui, Martin.", "." },
  ["2433691cafcbcbd6"] = { "Proprio così. La ⟦Scarlet Crusade=Crociata Scarlatta⟧ è un'aberrazione dell'Ordine della ⟦Silver Hand=Mano d'Argento⟧.\n\nDevi credermi, {race}: Taelan è un brav'uomo. Ha bisogno di una guida. Ha bisogno di ricordare... ricordare cosa significa essere nobile e onorevole. So che in cuor suo sa che ciò che fa è sbagliato. Lo aiuterai? Lo aiuterai a ricordare?", "." },
  ["24381cbb4f8c96fc"] = { "Skaldrenox! Possiedo il tuo scettro e ti intimo di entrare in questo mondo!", "." },
  ["243f35e1d9e4ca58"] = { "Grazie per il barile di liquore, {name}. Credo che ne stapperò una bottiglia subito!", "." },
  ["244b13024cc9d3b0"] = { "Se usiamo la teoria suriana, allora sì, ma non se seguiamo l'approccio y'seriano.", "." },
  ["245addbc8ee08b5e"] = { "Ora che il generale dei Piccatonante è stato sconfitto, possiamo spostare qualche truppa a guardia del ⟦Winterax Hold=Covo degli Asciafredda⟧. Ma dobbiamo restare sempre vigili, {class}, perché l'⟦Alliance=Alleanza⟧ tornerà.\n\nQuando li trovi ad aggirarsi furtivi, da' loro un'altra lezione!", "." },
  ["2461e75c716dfd9b"] = { "Ecco del cibo per te, Trok! Trok? Perché corri qua e là come un umano spaventato?", "." },
  ["2462d4cb214a4bde"] = { "Cerchi Urtrun Clanbringer nell'Ambasciata dell'⟦Horde=Orda⟧. La trovi sul lato ovest della ⟦Valley of Strength=Valle della Forza⟧.", "." },
  ["2463868fd665a7a7"] = { "%s avvista uno zombi da divorare!", "." },
  ["24692edd35a2914d"] = { "L'anziano Dawnstrider si trova a ⟦Flame Crest=Cimiero Ardente⟧, nelle ⟦Burning Steppes=Steppe Ardenti⟧.", "." },
  ["246db1f2d7aa84a4"] = { "Ho vestito dei re. Con l'addestramento giusto, potrai farlo anche tu.", "." },
  ["2473a26572c07e7d"] = { "Che meraviglia vedere i fiorellini resistere al freddo di Dun Morogh... ma qui fuori non troverai erboristi. Dovrai andare a ⟦Ironforge=Forgiardente⟧ per addestrarti in quella professione.", "." },
  ["2476c862082c2c36"] = { "Quei goblin dovrebbero vergognarsi. Bah!", "." },
  ["2483a6bab5f615d9"] = { "%s ha quasi recuperato tutte le forze!", "." },
  ["248df58fe930185a"] = { "<Mio/Mia> <signore/signora>, ti prego, lasciami vivere abbastanza da vederti purificare questo mondo dagli infedeli.", "." },
  ["24940e71d13dea19"] = { "%s si ritrae per il dolore quando il Judgement of Wisdom lo investe!", "." },
  ["249569c8a7ba6d6e"] = { "Per quello dovrai andare a Orgrimmar. Segui la strada che esce da ⟦Razor Hill=Tranciacolle⟧ verso nord attraverso il canyon e ci arriverai. Quando sei lì, chiedi a uno dei grunt altre indicazioni.", "." },
  ["249a3b5023b5f219"] = { "Salute, {class}. Provo pietà per quelli come te, perché i segreti della vera magia sono fuori dalla tua portata...", "." },
  ["249ec5d4b5c460a8"] = { "Ti copro io, Slidore, ma a dirla tutta puzzi davvero. Fatti una doccia, amico.", "." },
  ["249ed804bb73711f"] = { "In coscienza non posso permetterti di cercare Volcor finché non ti avrò confezionato quel mantello.", "." },
  ["24a17db250784851"] = { "C'è un erborista che vive sulle colline a est di ⟦Stormwind=Roccavento⟧ con il nostro alchimista. Una coppia davvero utile, non trovi?", "." },
  ["24a2e5fc8ca22254"] = { "Soffrirai in questa sconfitta, Nefarian!", "." },
  ["24a71472a8b17bce"] = { "Ma se lo stabilizziamo con un filo d'ancoraggio nel giusto crocevia energetico, allora dovrebbe funzionare.", "." },
  ["24b0fcbb81e8495d"] = { "«Darnassae?»\n\nLa druida elfa della notte ti guarda in attesa, ma è chiaro che non puoi comunicare con lei a parole. Senza scoraggiarsi, indica se stessa e sorride. Indica te e sorride ancora. Infine fa più volte cenno lungo il sentiero verso nord.\n\nForse vuole dirti che più avanti lungo la strada c'è un druido con cui potrai parlare?", "." },
  ["24b2b7591aa9cf7b"] = { "%s segue {name}.", "." },
  ["24bef9ec5a364a44"] = { "I miei colleghi e io stiamo raccogliendo le sostanze più letali che conosciamo e ne stiamo testando gli effetti sui nostri nemici. Quando avrò tutto ciò che mi serve, preparerò pestilenze come questo mondo non ne ha mai viste.", "." },
  ["24c0c1adac216ce8"] = { "Lucius è un vecchio e fidato amico del ⟦Ravenholdt Manor=Maniero dei Corvolesto⟧: abbiamo molto di cui parlare. Trovami al molo di ⟦Lakeshire=Borgolago⟧, se avrai bisogno del mio aiuto o dei miei consigli.", "." },
  ["24c2788b35afc01c"] = { "Bene, {name}. Ti dedichi al compito che hai davanti e sai cercare ciò che serve.\n\nMi basta un altro campione per creare il reagente necessario per il tuo sapta. Anche Islen ne sarà contenta.", "." },
  ["24c652dba5f9b8e5"] = { "Bene, <amico/amica> <mio/mia>, hai raggiunto vette che alcuni possono solo sognare. Complimenti! E ora, senza ulteriori cerimonie, è il momento della tua ultima lezione!", "." },
  ["24c8940da641e793"] = { "Abbiamo un gran surplus di rifornimenti, ma ce ne servono ancora prima di poter lanciare un assalto nel ⟦Field of Strife=Pian della Discordia⟧.", "." },
  ["24d069203771ef41"] = { "La pestilenza del Flagello domina ancora la zona, e c'è ancora molta strada da fare prima che la pestilenza sia alterata abbastanza da colpirli. Raccogli le risorse necessarie e dai una mano allo sforzo bellico!", "." },
  ["24d30eed1f16d15c"] = { "Forze oscure premono ai nostri confini, antiche corruzioni riaffiorano e nuovi mali emergono per rovesciare il delicato equilibrio della terra. In tempi così bui, dobbiamo tutti restare vigili.", "." },
  ["24d406484e28a8af"] = { "Ishnu-dal-dieb, {name}. Sei qui in cerca di conoscenza?", "." },
  ["24d4c6d89768f33a"] = { "⟦Tower Point=Torre Granguardia⟧ controlla il passo tra il ⟦Field of Strife=Pian della Discordia⟧ e i territori dell'⟦Horde=Orda⟧ a sud.\n\nÈ sotto il controllo dell'⟦Horde=Orda⟧.", "." },
  ["24d9c208e95530bb"] = { "I cacciatori e i ranger di Zephras non sono mai stati così necessari. I venti si fanno sempre più impetuosi, e la magia che sostiene la nostra isola sta svanendo. Le terre selvagge non sono mai state così selvagge, e c'è bisogno di gente come me per proteggere il nostro popolo.\n\nSe hai le giuste attitudini come {class}, posso darti gli strumenti per sopravvivere nelle terre selvagge.", "." },
  ["24dd4595d30c14ab"] = { "L'abilità con cui Telonis forgia le armature non ha eguali. Dovresti essergli riconoscente, perché non chiede di più per il sapere che trasmette agli altri. Ora va' a cercarlo nella ⟦Craftsmen's Terrace=Terrazza degli Artigiani⟧, nella parte nord-orientale di Darnassus.", "." },
  ["24e02f01b9e3061e"] = { "Lunga vita a {name}!", "." },
  ["24e16ad94ff16e57"] = { "La battaglia per la ⟦Warsong Gulch=Forra dei Cantaguerra⟧ comincia tra 1 minuto.", "." },
  ["24e4cb62b0cad57e"] = { "Ehm... credo che tu sia un po' troppo <grosso/grossa> per cavalcare un tecnostruzzo, <signore/signora>. Finiresti per schiacciare i servobilanciatori finemente regolati!", "." },
  ["24ea2ed589d0430e"] = { "Per Lothar, feccia dei Defias, la pagherete!", "." },
  ["24f250a9e060a99c"] = { "Intrusi al Service Gate! Bisogna avvertire il barone Rivendare!", "." },
  ["24f27c6f8ca14a2c"] = { "I silitidi non possono nulla contro i figli e le figlie di Orgrimmar. Presto di loro non resteranno che arti e ali schiacciati sotto i nostri piedi, {name}.", "." },
  ["24f7b098a97d68e5"] = { "Piccolo Reietto conosce tutte armi. Lui Archibald. Tu trova su anello interno di ⟦War Quarter=Quartiere della Guerra⟧.", "." },
  ["24fe2dff81f9f24e"] = { "Ma che squack??? Squack squack, squack? SQUACK!", "." },
})
